UPDATE "regulatory"."requirement_applicabilities" SET "updated_at" = "created_at" WHERE "updated_at" IS NULL;
ALTER TABLE "regulatory"."requirement_applicabilities" ALTER COLUMN "updated_at" SET DEFAULT CURRENT_TIMESTAMP, ALTER COLUMN "updated_at" SET NOT NULL;
ALTER TABLE "regulatory"."requirement_applicabilities" ADD CONSTRAINT "ck_requirement_applicabilities__updated_actor_one" CHECK (num_nonnulls(updated_by_user_identity_id, updated_by_service_principal_id) <= 1), ADD CONSTRAINT "ck_requirement_applicabilities__row_version_positive" CHECK (row_version > 0);
ALTER TABLE "regulatory"."requirement_applicabilities" ADD CONSTRAINT "fk_requirement_applicabilities__updated_by_user_identity_id" FOREIGN KEY ("updated_by_user_identity_id") REFERENCES "iam"."user_identities" ("user_identity_id") ON UPDATE NO ACTION ON DELETE RESTRICT, ADD CONSTRAINT "fk_requirement_applicabilities__updated_by_service_principal_id" FOREIGN KEY ("updated_by_service_principal_id") REFERENCES "iam"."service_principals" ("service_principal_id") ON UPDATE NO ACTION ON DELETE RESTRICT;

